export const tasteTraditionId = (number: StoryLessonNumber) => `conversational-skills-L6-C3-${number}-${tasteTraditionEpisodes[number].skill}-en-v1`;

export function buildTasteTraditionLesson(number: StoryLessonNumber, previous: any = {}, reference?: any) {
  const index = storyLessonNumbers.indexOf(number);
  const lesson = buildEnglishExpressionLesson(number, tasteTraditionEpisodes[number], previous, reference, {
    id: tasteTraditionId(number), chapterName: 'The Taste of Tradition', pronunciation: naturalPronunciationLessons[3][number],
    setting: 'A fictional culinary heritage project based in Kyoto, with an obanzai meal, a family pickle shop, a traditional brewery visit in Yuasa, Wakayama, Mrs. Okabe’s kitchen and a Kyoto event. Real food traditions support fictional people and arrangements.',
    previousSummary: index === 0 ? beyondWorkshopEpisodes[9].closing : tasteTraditionEpisodes[storyLessonNumbers[index - 1]!].closing,
    storyNotes: `${conversationalLanguageInstructions(6)}\nReference: The Taste of Tradition. Eight episodes map to regular slots 1-4 and 6-9; 5/10 remain dynamic checkpoints. English only, four contextual Step A expressions, standard guides, tutor-first roles, private listening, fresh visible reading notes and fixed English feedback. Step B uses natural connected speech, clear grouping and precisely bolded stress. No new images, romance or inherited Kyoto-residence/Tokyo-mystery plots. Obanzai is a home-style tradition, not one fixed menu or a guarantee of dietary suitability. Pickling methods differ; not all are long-fermented. Brewing visits explain factors rather than supply operational recipes, temperatures, readiness tests or food-safety advice. No exact prices or times are invented. The key ethical change is Mei recognising voluntary sharing and private transmission. Mrs. Okabe’s granddaughter is learning the private grandmother recipe. Story permission does not include that recipe. Mei decides on a voluntary plan before organisers accept it in episode seven/slot eight. Perhaps one day is not a promise of public classes. At the end, the handwritten recipe is Mrs. Okabe’s own different creation, offered for students and visitors; it is not a reward that reveals the secret or an unlimited commercial licence. Keep younger visitors’ interest separate from enrolment. End with the friends at Mei’s restaurant and the cleaning joke, without inventing a sequel.`,
  });
  lesson.storyData.storyTitle = 'Threads of Tradition';
  lesson.storyData.characters = [
    { id: 'mei', name: 'Mei', role: 'main', description: 'Chef from Kyoto and event organiser. She learns to respect different forms of preservation and voluntary sharing.' },
    { id: 'aiko', name: 'Aiko', role: 'supporting', description: 'Museum educator based in Tokyo. She researches family food histories and asks whose choices shape the project.' },
    { id: 'haru', name: 'Haru', role: 'supporting', description: 'Kanazawa family-workshop member. He contacts producers and compares public demonstrations with longer apprentice learning.' },
    { id: 'daniel', name: 'Daniel', role: 'supporting', description: 'Canadian photographer living in Japan. He documents activities, asks about sharing and discovers a comic enthusiasm for barrels.' },
    { id: 'ishida', name: 'Mr. Ishida', role: 'supporting', description: 'Fictional Kyoto pickle producer. He explains differing methods, distinctive flavours and the need for sustainable work.' },
    { id: 'guide', name: 'Brewery guide', role: 'supporting', description: 'Fictional guide at a traditional Yuasa brewery. She explains how time, conditions, technology and experience affect production.' },
    { id: 'okabe', name: 'Mrs. Okabe', role: 'supporting', description: 'Fictional Kyoto cook. She teaches a private family recipe to her granddaughter, shares memories and later offers a different recipe of her own.' },
  ];
  if (number === 4) {
    lesson.applyData.tutorSteps[0].scripts[0].text = "I'll be the brewery guide. Please be Mei. Is it clear? I'll start.";
    lesson.missionData.tutorSteps[1].scripts[0].text = "I'll be the brewery guide. Please be Haru. You may use the useful language. I'll start.";
  }
  return { ...lesson, course: 'conversational-skills', level: 6, chapter: 3, lessonNumber: number,
    levelBadge: 'INTERMEDIATE', chapterLabel: 'Chapter 3: The Taste of Tradition', status: previous.status || 'draft',
    overlayColor: previous.overlayColor || '#17252bcc', supportLanguage: 'en', authoringLanguageTarget: 'TOEIC 550-780', authoringLanguageRevision: 'toeic-v1' };
}

export function buildTasteTraditionChapter(reference?: any) {
  return storyLessonNumbers.map(number => buildTasteTraditionLesson(number, {}, reference));
}
